package com.biblereader.app.ui

/** Curated, offline study notes. These are editorial summaries, not Scripture. */
data class ReadingPlanDay(val number: Int, val reference: String, val title: String, val book: String, val chapter: Int)

data class StudyEntry(
    val title: String,
    val subtitle: String,
    val category: String,
    val body: String,
    val references: List<String>
)

object StudyContent {
    val dictionaryEntries = listOf(
        StudyEntry("Atonement", "Reconciliation and dealing with sin", "Dictionary", "Atonement describes how the barrier created by sin is dealt with so that people may be reconciled to God. The Bible develops this theme through sacrifice, forgiveness and the work of Jesus.", listOf("Leviticus 16", "Romans 3", "Hebrews 9")),
        StudyEntry("Covenant", "A committed relationship and promise", "Dictionary", "A covenant is a solemn commitment. Biblical covenants structure key relationships between God and people, carrying promises as well as responsibilities.", listOf("Genesis 15", "Exodus 19", "Jeremiah 31")),
        StudyEntry("Disciple", "A learner and follower", "Dictionary", "A disciple is someone who learns from and follows a teacher. In the Gospels, Jesus calls people not only to hear his teaching but to follow him in daily life.", listOf("Luke 9", "Luke 14", "John 8")),
        StudyEntry("Gospel", "Good news", "Dictionary", "Gospel means good news. In the New Testament it refers especially to the announcement of what God has done through Jesus: his life, death and resurrection.", listOf("Mark 1", "Romans 1", "1 Corinthians 15")),
        StudyEntry("Grace", "God's generous gift", "Dictionary", "Grace is God's generous favour, not something people can earn. The New Testament connects grace with forgiveness, salvation and a transformed life.", listOf("John 1", "Romans 5", "Ephesians 2")),
        StudyEntry("Kingdom of God", "God's reign", "Dictionary", "The kingdom of God refers to God's rule and reign. Jesus announces it, demonstrates its values and teaches his followers to pray for its coming in fullness.", listOf("Matthew 6", "Mark 1", "Luke 17")),
        StudyEntry("Messiah", "The anointed one", "Dictionary", "Messiah comes from a word meaning anointed one. Israel's hopes for an anointed king and deliverer form an important background to the New Testament's identification of Jesus as the Christ.", listOf("2 Samuel 7", "Isaiah 9", "John 1")),
        StudyEntry("Parable", "A story that teaches", "Dictionary", "A parable is a short story or comparison that invites listeners to consider a deeper truth. Jesus often uses parables to reveal the surprising character of God's kingdom.", listOf("Matthew 13", "Luke 10", "Luke 15")),
        StudyEntry("Repentance", "Turning back to God", "Dictionary", "Repentance involves a change of mind and direction: turning away from sin and returning to God. Biblical repentance is more than regret; it is expressed in a changed life.", listOf("Isaiah 55", "Mark 1", "Acts 2")),
        StudyEntry("Righteousness", "Right relationship and just conduct", "Dictionary", "Righteousness can describe God's faithfulness and justice, and the right conduct expected of people. In the New Testament it is closely connected to God's saving work and a life shaped by faith.", listOf("Psalm 15", "Matthew 5", "Romans 3")),
        StudyEntry("Salvation", "Rescue and restoration", "Dictionary", "Salvation means rescue from danger and, in Scripture, especially God's deliverance from sin and death. The Bible presents salvation as God's work, received through faith and leading to new life.", listOf("Luke 19", "Romans 10", "Ephesians 2")),
        StudyEntry("Sanctification", "Being set apart for God", "Dictionary", "Sanctification describes being set apart for God and growing in a life shaped by holiness. The New Testament connects this growth with the work of the Holy Spirit and practical love.", listOf("John 17", "1 Thessalonians 4", "1 Peter 1")),
        StudyEntry("Sin", "Human rebellion and brokenness", "Dictionary", "Sin describes actions and attitudes that oppose God's will and damage relationships with God and others. Scripture treats sin seriously while also proclaiming God's forgiveness and restoration.", listOf("Genesis 3", "Romans 3", "1 John 1")),
        StudyEntry("Testament", "Covenant; a division of the Bible", "Dictionary", "Testament can mean covenant. The terms Old Testament and New Testament refer to the two major collections of Scripture in the Christian Bible, centred on God's covenant story and its fulfilment in Christ.", listOf("Jeremiah 31", "Luke 22", "Hebrews 8"))
    )

